window.kbPageData["views/entry/k-ea520e2231b55fe0"] = {"key":"entry/k-ea520e2231b55fe0","state":{"route":"entry/k-ea520e2231b55fe0"},"node":{"id":"k-ea520e2231b55fe0","mode":"k","title":"生成与形成","type":"概念与词义","domain":"汉语","reading":"","intro":"","priority":100,"aliases":["“生成”的词义及其与“新组织”的搭配"],"qs":["江苏 2025 A类 行测#39"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"“生成”侧重由某个过程产生新的事物，“形成”侧重经过发展变化而成为某种事物或状态。两词在描述新组织出现时有语义重叠。","review":{"definition":"“生成”侧重由某个过程产生新的事物，“形成”侧重经过发展变化而成为某种事物或状态。两词在描述新组织出现时有语义重叠。","explanation":"题干先说领导细胞迅速闭合伤口，再说细胞增殖，第二空的“生成新组织”着重表达新组织的产生。科技日报原报道第一空用“一马当先”，第二空用“制造新组织”，可为C项第一空提供直接依据。医学报道也有“形成新组织”的用例，第二空的搭配本身不足以排除B项。","references":[{"source":"web-099fc53bca60daab","location":"正文末段","quote":"这些细胞一马当先"},{"source":"web-4129a1cc372d1bf4","location":"正文首段","quote":"细胞则活下来形成新组织"}],"evidence":"肝脏优先考虑闭合伤口，防止细菌进入器官引起广泛感染。","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2025 A类 行测#39":{"paper":"江苏 2025 A类 行测","n":39,"mod":"言语理解与表达","src":["98687766ac277f427cd6.pdf",9],"asrc":["4fe8e0544dd7b47699d2.pdf",13],"card":"09f5a3ddb663dcddb89bda0e","links":[{"id":"k-ea520e2231b55fe0","role":"直接考查","why":"“生成”可指经自然过程产生，此处贴合细胞增殖并产生新组织的语境。"}]}},"terms":{},"references":{"web-099fc53bca60daab":{"name":"科技日报《修复受损肝脏的新型细胞发现》（科学网转载）","url":"https://wap.sciencenet.cn/mobile.php?cat=news&id=522575&mobile=1&type=detail"},"web-4129a1cc372d1bf4":{"name":"科技日报《可降解纳米球搭载细胞修复伤口》（中国教育和科研计算机网转载）","url":"https://www.edu.cn/yi_liao_bao_xian_1129/20110419/t20110419_602998.shtml"}},"topics":[],"units":{"k-ea520e2231b55fe0":[["江苏 2025 A类 行测#39"]]}};
